namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string Room { get; set; }
    public required Instructor Instructor { get; set; }
    public required Department Department { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Name { get; set; }
    public required string Description { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Title { get; set; }
    public required string Email { get; set; }
    public required string Bio { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    [StringLength(500)]
    public string? Notes { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, data structures, and the design of software and hardware systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Exploration of abstract structures, quantities, and patterns through rigorous proof and analysis." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Investigation of matter, energy, and the fundamental forces that govern the natural world." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Critical reading, writing, and analysis of literature and language across historical and cultural contexts." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events, societies, and civilizations to understand the forces that shape the present." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Email = "achen@university.edu", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 peer-reviewed papers and leads the university's AI research lab." },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Computer Science", Email = "rmartinez@university.edu", Bio = "Dr. Martinez focuses on software engineering and distributed systems. He spent 10 years in industry at major tech companies before joining academia." },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor of Mathematics", Email = "sjohnson@university.edu", Bio = "Dr. Johnson is an expert in applied mathematics and statistics. She has received multiple NSF grants for her work in computational modeling." },
            new() { Id = 4, Name = "Dr. James Wilson", Title = "Associate Professor of Physics", Email = "jwilson@university.edu", Bio = "Dr. Wilson researches quantum mechanics and condensed matter physics. He is known for his engaging lectures and hands-on lab approach." },
            new() { Id = 5, Name = "Prof. Emily Davis", Title = "Professor of English", Email = "edavis@university.edu", Bio = "Prof. Davis is a specialist in 19th-century American literature and creative writing. She has authored three novels and a widely used composition textbook." },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Professor of History", Email = "mbrown@university.edu", Bio = "Dr. Brown studies modern European history with a focus on the 20th century. He has written extensively on post-war reconstruction and diplomacy." },
            new() { Id = 7, Name = "Dr. Lisa Park", Title = "Assistant Professor of Mathematics", Email = "lpark@university.edu", Bio = "Dr. Park specializes in number theory and cryptography. She previously worked as a cryptanalyst before transitioning to academic research." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to the field of computer science covering computational thinking, basic programming in Python, data representation, and an overview of how computers work.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201", Instructor = _instructors[0], Department = _departments[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM", Room = "Science Hall 305", Instructor = _instructors[1], Department = _departments[0] },
            new() { Id = 3, Code = "CS 310", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning fundamentals, natural language processing, and ethical considerations in AI development.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Room = "Science Hall 401", Instructor = _instructors[0], Department = _departments[0], IsFeatured = true },
            new() { Id = 4, Code = "CS 350", Title = "Software Engineering", Description = "Principles and practices of software development including requirements analysis, design patterns, testing strategies, version control, agile methodologies, and team-based project work.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Room = "Science Hall 210", Instructor = _instructors[1], Department = _departments[0] },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, continuity, derivatives of single-variable functions, and an introduction to integration. Applications include rates of change, optimization, and area under curves.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Math Building 110", Instructor = _instructors[2], Department = _departments[1], IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations. Applications in computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", Room = "Math Building 215", Instructor = _instructors[6], Department = _departments[1] },
            new() { Id = 7, Code = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian inference with applications to real-world data sets.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Math Building 120", Instructor = _instructors[2], Department = _departments[1] },
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Classical mechanics covering kinematics, Newton's laws, work and energy, momentum, rotational motion, and gravitation. Includes a weekly hands-on laboratory session.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:00 PM", Room = "Physics Lab 100", Instructor = _instructors[3], Department = _departments[2], IsFeatured = true },
            new() { Id = 9, Code = "PHYS 205", Title = "Modern Physics", Description = "Introduction to relativity, quantum mechanics, atomic and nuclear physics, and particle physics. Bridges classical physics to the modern understanding of the universe.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", Room = "Physics Lab 205", Instructor = _instructors[3], Department = _departments[2] },
            new() { Id = 10, Code = "ENG 101", Title = "Composition and Rhetoric", Description = "Development of college-level writing skills through essays, research papers, and peer workshops. Emphasis on argumentation, evidence, clarity, and revision.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Humanities 310", Instructor = _instructors[4], Department = _departments[3] },
            new() { Id = 11, Code = "ENG 220", Title = "American Literature Survey", Description = "Survey of major works in American literature from the colonial period to the present, exploring themes of identity, democracy, and the American experience.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", Room = "Humanities 225", Instructor = _instructors[4], Department = _departments[3] },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "A global survey of human civilizations from prehistory through the late medieval period, covering the rise and fall of empires, cultural exchange, and technological development.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Liberal Arts 105", Instructor = _instructors[5], Department = _departments[4] },
            new() { Id = 13, Code = "HIST 250", Title = "20th Century World History", Description = "Examination of the major political, social, and cultural transformations of the 20th century including world wars, decolonization, the Cold War, and globalization.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", Room = "Liberal Arts 210", Instructor = _instructors[5], Department = _departments[4], IsFeatured = true },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null, int? credits = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.Department.Id == departmentId.Value);

        if (credits.HasValue)
            query = query.Where(c => c.Credits == credits.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Department.Code).ThenBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<int> GetDistinctCredits() => _courses.Select(c => c.Credits).Distinct().OrderBy(c => c).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

