+@page "/enroll"
+@using UniversityCourseCatalog.Models
+@using UniversityCourseCatalog.Services
+@inject CatalogService Catalog
+
+<PageTitle>Enroll – University Course Catalog</PageTitle>
+
+<h1 class="mb-4">Enrollment Request</h1>
+
+@if (submitted)
+{
+    <div class="alert alert-success">
+        <h4 class="alert-heading">Request Submitted</h4>
+        <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
+            <strong>@selectedCourseTitle</strong> has been received.</p>
+        <hr />
+        <p class="mb-0">You will receive a confirmation at your university email. <a href="/courses">Browse more courses</a>.</p>
+    </div>
+}
+else
+{
+    <p class="text-muted mb-4">Fill out the form below to request enrollment in a course. All fields marked with <span class="text-danger">*</span> are required.</p>
+
+    <div class="row">
+        <div class="col-lg-8">
+            <form method="post" @formname="enrollment">
+                <AntiforgeryToken />
+
+                <div class="mb-3">
+                    <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
+                    <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
+                    <ValidationMessage For="() => Model.FullName" />
+                </div>
+
+                <div class="mb-3">
+                    <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
+                    <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. STU-12345" />
+                    <ValidationMessage For="() => Model.StudentId" />
+                </div>
+
+                <div class="mb-3">
+                    <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
+                    <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
+                        <option value="0">-- Select a course --</option>
+                        @foreach (var course in courses)
+                        {
+                            <option value="@course.Id">@course.Code – @course.Title (@course.Credits cr)</option>
+                        }
+                    </InputSelect>
+                    <ValidationMessage For="() => Model.CourseId" />
+                </div>
+
+                <div class="mb-3">
+                    <label for="notes" class="form-label">Notes (optional)</label>
+                    <InputTextArea id="notes" @bind-Value="Model.Notes" class="form-control" rows="3" placeholder="Any special requests or comments…" />
+                    <ValidationMessage For="() => Model.Notes" />
+                </div>
+
+                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
+                <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
+
+                <DataAnnotationsValidator />
+                <ValidationSummary class="text-danger mt-3" />
+            </form>
+        </div>
+    </div>
+}
+
+@code {
+    [SupplyParameterFromForm] private EnrollmentRequest Model { get; set; } = new();
+    [SupplyParameterFromQuery] public int? CourseId { get; set; }
+
+    private List<Course> courses = new();
+    private bool submitted;
+    private string selectedCourseTitle = "";
+
+    protected override void OnInitialized()
+    {
+        courses = Catalog.GetCourses();
+
+        if (CourseId.HasValue && Model.CourseId == 0)
+        {
+            Model.CourseId = CourseId.Value;
+        }
+    }
+
+    protected override void OnParametersSet()
+    {
+        if (HttpMethods.IsPost(httpContext?.Request.Method ?? ""))
+        {
+            if (IsValid())
+            {
+                var course = Catalog.GetCourse(Model.CourseId);
+                selectedCourseTitle = course is not null ? $"{course.Code} – {course.Title}" : "Unknown Course";
+                Catalog.SubmitEnrollmentRequest(Model);
+                submitted = true;
+            }
+        }
+    }
+
+    [CascadingParameter] private HttpContext? httpContext { get; set; }
+
+    private bool IsValid()
+    {
+        var context = new System.ComponentModel.DataAnnotations.ValidationContext(Model);
+        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
+        return System.ComponentModel.DataAnnotations.Validator.TryValidateObject(Model, context, results, true);
+    }
+}
+

